const STORAGE_KEY = 'capsule-wardrobe-web-v1';
const OUTFIT_STORAGE_KEY = 'capsule-wardrobe-outfits-v1';
const CANVAS_STORAGE_KEY = 'capsule-wardrobe-canvas-v1';
const FOLDER_STORAGE_KEY = 'capsule-wardrobe-folders-v1';
const asset = (name) => `./assets/clothes/${name}.jpg`;
const seed = [
  {id:'blue-shirt',name:'浅蓝衬衫与领带',category:'上衣',color:'浅蓝',style:['通勤','学院'],season:['春','秋'],keywords:['衬衫','领带','利落'],worn:7,image:asset('white-shirt')},
  {id:'denim-jeans',name:'经典牛仔裤',category:'下装',color:'丹宁蓝',style:['休闲','极简'],season:['春','秋'],keywords:['牛仔','日常','直筒'],worn:4,image:asset('denim-jeans')},
  {id:'brown-bomber',name:'焦糖色飞行夹克',category:'外套',color:'焦糖棕',style:['休闲','复古'],season:['春','秋'],keywords:['夹克','层次','轻外套'],worn:2,image:asset('black-blazer')},
  {id:'evening-dress',name:'莓果色露肩礼服',category:'连衣裙',color:'莓果紫',style:['优雅','派对'],season:['春','夏'],keywords:['约会','礼服','质感'],worn:1,image:asset('satin-dress')},
  {id:'floral-heels',name:'蓝色花卉高跟鞋',category:'鞋子',color:'天蓝',style:['复古','亮点'],season:['春','夏'],keywords:['花卉','高跟','点睛'],worn:8,image:asset('leather-loafers')},
  {id:'check-scarf',name:'格纹围巾',category:'配饰',color:'深灰',style:['温柔','复古'],season:['秋','冬'],keywords:['围巾','保暖','格纹'],worn:0,image:asset('cashmere-scarf')}
];
let state = { clothes: [], outfits: [], selected: [], filters: {category:'',color:'',style:''}, previewImage: '', canvasLayout: {}, activeCanvasPiece: '', folders: [], activeFolder: '' };
let dragging = null;
function $(selector){ return document.querySelector(selector); }
function $all(selector){ return [...document.querySelectorAll(selector)]; }
function esc(str=''){ const node=document.createElement('div'); node.textContent=str; return node.innerHTML; }
function getDisplayImage(piece){ return piece.cutoutImage || piece.image; }
function toast(message){ const node=$('#toast'); node.textContent=message; node.classList.add('show'); clearTimeout(window.toastTimer); window.toastTimer=setTimeout(()=>node.classList.remove('show'),2200); }
function load(){
  try {
    const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));
    const legacy=['white-shirt','denim-jeans','black-blazer','silk-dress','leather-loafers','scarf'];
    const isLegacy=Array.isArray(saved)&&saved.length===legacy.length&&saved.every(item=>legacy.includes(item.id));
    state.clothes=!saved||isLegacy?structuredClone(seed):saved;
    state.outfits=JSON.parse(localStorage.getItem(OUTFIT_STORAGE_KEY))||[];
    state.canvasLayout=JSON.parse(localStorage.getItem(CANVAS_STORAGE_KEY))||{};
    state.folders=JSON.parse(localStorage.getItem(FOLDER_STORAGE_KEY))||[];
    if(isLegacy)save();
  } catch { state.clothes=structuredClone(seed); }
}
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state.clothes));}
function saveCanvas(){localStorage.setItem(CANVAS_STORAGE_KEY,JSON.stringify(state.canvasLayout));}
function saveFolders(){localStorage.setItem(FOLDER_STORAGE_KEY,JSON.stringify(state.folders));}
function selectedClothes(){return state.selected.map(id=>state.clothes.find(x=>x.id===id)).filter(Boolean);}
function uniq(field){return [...new Set(state.clothes.flatMap(x=>Array.isArray(x[field])?x[field]:[x[field]]))];}
function renderChips(id,values,current,key){$(id).innerHTML=[['','全部'],...values.map(v=>[v,v])].map(([value,label])=>`<button class="chip ${value===current?'active':''}" data-filter="${key}" data-value="${esc(value)}" type="button">${esc(label)}</button>`).join('');}
function folderList(){return[{id:'spring-summer',name:'春夏',match:piece=>piece.season?.some(season=>['春','夏'].includes(season))},{id:'autumn-winter',name:'秋冬',match:piece=>piece.season?.some(season=>['秋','冬'].includes(season))},{id:'tops',name:'上衣',match:piece=>piece.category==='上衣'},{id:'bottoms',name:'下装',match:piece=>piece.category==='下装'||piece.category==='连衣裙'},{id:'outerwear',name:'外套',match:piece=>piece.category==='外套'},{id:'shoes-accessories',name:'鞋履与配饰',match:piece=>['鞋子','配饰'].includes(piece.category)},...state.folders.map(folder=>({id:folder.id,name:folder.name,match:piece=>(piece.folders||[]).includes(folder.id)}))];}
function folderMatches(piece){if(!state.activeFolder)return true;return folderList().find(folder=>folder.id===state.activeFolder)?.match(piece)||false;}
function filtered(){return state.clothes.filter(piece=>folderMatches(piece)&&Object.entries(state.filters).every(([key,value])=>!value||(Array.isArray(piece[key])?piece[key].includes(value):piece[key]===value)));}
function renderWardrobe(){
  renderChips('#category-filters',uniq('category'),state.filters.category,'category'); renderChips('#color-filters',uniq('color'),state.filters.color,'color'); renderChips('#style-filters',uniq('style'),state.filters.style,'style');
  const items=filtered(),folders=folderList();
  $('#wardrobe-count').textContent=state.clothes.length;
  $('#wardrobe-filter-count').textContent='件衣物';
  $('#closet-home').hidden=Boolean(state.activeFolder); $('#closet-detail').hidden=!state.activeFolder;
  if(!state.activeFolder){$('#wardrobe-shelves').innerHTML=folders.map(folder=>{const pieces=state.clothes.filter(folder.match);return `<button class="wardrobe-folder" type="button" data-folder="${folder.id}"><span class="folder-label">${esc(folder.name)}</span><span class="folder-count">${pieces.length} 件</span><div class="folder-rail">${pieces.slice(0,5).map(piece=>`<img src="${getDisplayImage(piece)}" alt="${esc(piece.name)}">`).join('')}</div></button>`;}).join('');return;}
  const folder=folders.find(item=>item.id===state.activeFolder); $('#folder-title').textContent=folder?.name||'衣物';
  $('#closet-grid').innerHTML=items.map(piece=>`<article class="clothing-card ${state.selected.includes(piece.id)?'selected':''}" data-piece="${piece.id}" tabindex="0" role="button" aria-pressed="${state.selected.includes(piece.id)}"><div class="clothing-image" style="background-image:url('${getDisplayImage(piece)}')"></div><span class="select-tick">${state.selected.includes(piece.id)?'✓':''}</span><div class="card-body"><p>${esc(piece.name)}</p><small>${esc(piece.category)} · ${esc(piece.color)}</small></div></article>`).join('');
  $('#empty-wardrobe').hidden=items.length>0; $('#selection-bar').hidden=state.selected.length===0; $('#selected-count').textContent=state.selected.length;
}
function defaultLayout(piece,index){const defaults={上衣:[50,26,1],下装:[50,66,.93],连衣裙:[50,49,1.08],外套:[50,35,1.05],鞋子:[30,84,.6],配饰:[74,25,.55]};const [x,y,scale]=defaults[piece.category]||[50+(index%2)*16,35+index*13,.8];return{x,y,scale,rotation:0,z:index+1};}
function layoutFor(piece,index){if(!state.canvasLayout[piece.id])state.canvasLayout[piece.id]=defaultLayout(piece,index);return state.canvasLayout[piece.id];}
function updateCanvasToolbar(){const active=state.canvasLayout[state.activeCanvasPiece];$('#canvas-piece-name').textContent=state.clothes.find(piece=>piece.id===state.activeCanvasPiece)?.name||'衣物';$all('[data-canvas-adjust]').forEach(button=>button.disabled=!active);}
function renderCanvas(){
  const selected=selectedClothes(),canvas=$('#outfit-canvas');
  if(!selected.length){canvas.innerHTML='<div class="canvas-empty"><span>✦</span><h2>从衣橱开始组合</h2><p>选中衣物后，按住图片即可自由拖动。</p></div>';$('#canvas-toolbar').hidden=true;return;}
  selected.forEach((piece,index)=>layoutFor(piece,index)); if(!selected.some(piece=>piece.id===state.activeCanvasPiece))state.activeCanvasPiece=selected[0].id;
  canvas.innerHTML=selected.map((piece,index)=>{const layout=layoutFor(piece,index),active=state.activeCanvasPiece===piece.id;return `<button class="canvas-piece ${active?'active':''}" type="button" data-canvas-piece="${piece.id}" aria-label="拖动 ${esc(piece.name)}" style="--x:${layout.x}%;--y:${layout.y}%;--scale:${layout.scale};--rotation:${layout.rotation}deg;z-index:${layout.z}"><img src="${getDisplayImage(piece)}" alt="${esc(piece.name)}"><span>${esc(piece.name)}</span></button>`;}).join('');
  $('#canvas-toolbar').hidden=false; updateCanvasToolbar();
}
function renderStudio(){const selected=selectedClothes();$('#studio-count').textContent=selected.length;$('#studio-selection').innerHTML=selected.map(piece=>`<div class="selected-row"><img src="${getDisplayImage(piece)}" alt="${esc(piece.name)}"><p>${esc(piece.name)}<br><small>${esc(piece.category)} · ${esc(piece.color)}</small></p><button type="button" data-remove="${piece.id}" aria-label="移除 ${esc(piece.name)}">×</button></div>`).join('');$('#selection-help').hidden=selected.length>0;const navCount=$('#outfit-nav-count');navCount.textContent=selected.length;navCount.hidden=selected.length===0;$('#saved-outfits').innerHTML=state.outfits.slice(0,2).map((outfit,index)=>`<p class="saved-outfit">已保存搭配 ${state.outfits.length-index} · ${outfit.clothingIds.length} 件</p>`).join('');renderCanvas();}
function outfitDate(value){return new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric'}).format(new Date(value));}
function renderOOTD(){const outfits=state.outfits;$('#empty-ootd').hidden=outfits.length>0;$('#ootd-grid').innerHTML=outfits.map((outfit,index)=>{const pieces=outfit.clothingIds.map(id=>state.clothes.find(piece=>piece.id===id)).filter(Boolean);return `<article class="ootd-card"><div class="ootd-card-head"><span>LOOK ${String(outfits.length-index).padStart(2,'0')}</span><time>${outfitDate(outfit.createdAt)}</time></div><div class="ootd-pieces">${pieces.map(piece=>`<img src="${getDisplayImage(piece)}" alt="${esc(piece.name)}">`).join('')}</div><div class="ootd-card-footer"><b>${pieces.length} 件单品</b><span>${pieces.map(piece=>esc(piece.category)).join(' · ')}</span></div></article>`;}).join('');}
function renderAll(){renderWardrobe();renderStudio();renderOOTD();}
function setView(name){if(name==='quick-add'){openModal();return;}const view=['wardrobe','studio','ootd'].includes(name)?name:'wardrobe';$all('.view').forEach(node=>node.classList.toggle('active',node.dataset.view===view));$all('[data-nav]').forEach(node=>node.classList.toggle('active',node.dataset.nav===view));if(location.hash!==`#${view}`)history.replaceState(null,'',`#${view}`);window.scrollTo({top:0,behavior:'smooth'});}
function togglePiece(id){state.selected=state.selected.includes(id)?state.selected.filter(x=>x!==id):[...state.selected,id];renderWardrobe();renderStudio();}
function chooseComplements(selected){const priorities=['上衣','下装','外套','鞋子','配饰'],present=new Set(selected.map(x=>x.category)),need=priorities.filter(x=>!present.has(x)),picks=[...selected];for(const category of need){const match=state.clothes.find(x=>x.category===category&&!picks.some(p=>p.id===x.id));if(match&&picks.length<4)picks.push(match);}return picks.slice(0,4);}
function intentScore(piece,mood,occasion,keywords){const terms=[mood,occasion,...keywords.toLowerCase().split(/[、,，\s]+/)].filter(Boolean);const text=[piece.name,piece.category,piece.color,...(piece.style||[]),...(piece.keywords||[])].join(' ').toLowerCase();let score=piece.worn||0;terms.forEach(term=>{if(text.includes(term))score+=8;});if(occasion==='上班'&&['通勤','极简','学院'].some(tag=>(piece.style||[]).includes(tag)))score+=5;if(occasion==='约会'&&['优雅','复古'].some(tag=>(piece.style||[]).includes(tag)))score+=5;if(occasion==='周末出行'&&['休闲','舒适'].some(tag=>(piece.style||[]).includes(tag)))score+=5;if(mood==='干练专注'&&['上衣','外套'].includes(piece.category))score+=3;return score;}
function autoMatchOutfit(mood,occasion,keywords){const categories=occasion==='约会'&&state.clothes.some(piece=>piece.category==='连衣裙')?['连衣裙','外套','鞋子','配饰']:['上衣','下装','外套','鞋子'];const picks=[];categories.forEach(category=>{const matches=state.clothes.filter(piece=>piece.category===category&&!picks.some(pick=>pick.id===piece.id)).sort((a,b)=>intentScore(b,mood,occasion,keywords)-intentScore(a,mood,occasion,keywords));if(matches[0])picks.push(matches[0]);});return picks;}
function generateOutfit(){const locked=selectedClothes(),mood=$('#mood').value,occasion=$('#occasion').value,keywords=$('#keywords').value.trim(),hasLocked=locked.length>0,clothes=hasLocked?chooseComplements(locked):autoMatchOutfit(mood,occasion,keywords),missing=clothes.filter(x=>!locked.some(l=>l.id===x.id));if(!clothes.length){toast('衣橱里还没有可用于搭配的衣物');return;}const title=mood==='干练专注'?'利落的城市节奏':mood==='想有一点仪式感'?'轻盈而有光的时刻':mood==='低调舒适'?'安静但有质感':'松弛的日常配方';const sentence=hasLocked?`以${locked.map(x=>x.name).join('、')}为核心，${missing.length?`加入${missing.map(x=>x.name).join('和')}来平衡比例。`:'保持你已选单品的完整表达。'} ${occasion}场景里，${keywords?`“${keywords}”会成为今天的点睛方向。`:'选择干净的配色和清晰的轮廓，就足够有力量。'}`:`根据${mood}的心情和${occasion}场景，从衣橱中挑出${clothes.map(x=>x.name).join('、')}。${keywords?`“${keywords}”已作为这次筛选的风格方向。`:'这套搭配以颜色、风格与品类的平衡为优先。'}`;$('#outfit-advice').innerHTML=`<article class="outfit-result"><div class="result-intro"><div><p class="eyebrow">${hasLocked?'AROUND YOUR PICKS':'AI WARDROBE MATCH'} · ${esc(occasion)}</p><h2>${title}</h2><p>${sentence}</p></div><div class="score">${hasLocked?'92':'89'}<br><small>匹配</small></div></div><div class="outfit-pieces">${clothes.map(piece=>`<article class="outfit-piece"><img src="${getDisplayImage(piece)}" alt="${esc(piece.name)}"><p>${esc(piece.name)}</p><small>${hasLocked?(locked.some(x=>x.id===piece.id)?'已锁定':'建议补充'):'AI 匹配'} · ${esc(piece.category)}</small></article>`).join('')}</div><div class="result-tips"><b>${hasLocked?'围绕已选单品':'从衣橱自动匹配'}</b><br>${hasLocked?'已优先保留你的选择，并补齐整体比例。':'未选衣物时，会按心情、场景、关键词和衣物标签直接组合。'} 若气温下降，可优先叠加外套；鞋子和包选择相近的深浅，让视觉更完整。</div></article>`;}
function saveManualOutfit(){if(!state.selected.length){toast('先从衣橱选择衣物，再保存成一套');setView('wardrobe');return;}const layout={};state.selected.forEach(id=>{if(state.canvasLayout[id])layout[id]={...state.canvasLayout[id]};});state.outfits.unshift({id:`outfit-${Date.now()}`,clothingIds:[...state.selected],layout,createdAt:new Date().toISOString()});localStorage.setItem(OUTFIT_STORAGE_KEY,JSON.stringify(state.outfits));renderAll();toast('已保存这套组合与排版');}
function openModal(){const folderInput=$('#folder-input');folderInput.innerHTML='<option value="">未分类</option>'+state.folders.map(folder=>`<option value="${folder.id}">${esc(folder.name)}</option>`).join('');$('#add-modal').hidden=false;document.body.style.overflow='hidden';$('#add-form [name=name]').focus();}
function closeModal(){$('#add-modal').hidden=true;document.body.style.overflow='';state.previewImage='';$('#add-form').reset();$('#upload-preview').innerHTML='＋<small>从相册选择照片</small>';}
function makeFallback(name,color){return `data:image/svg+xml;charset=UTF-8,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 800"><rect width="640" height="800" fill="#ded8ce"/><circle cx="320" cy="310" r="120" fill="#${color.replace('#','')||'b7aaa0'}" opacity=".7"/><text x="50%" y="650" text-anchor="middle" font-family="Arial" font-size="36" fill="#5d574f">${name.slice(0,8)}</text></svg>`)}`;}
function addPiece(event){event.preventDefault();const data=new FormData(event.currentTarget),name=data.get('name').trim(),color=data.get('color').trim(),style=data.get('style').trim(),category=data.get('category'),season=data.get('season'),folder=data.get('folder'),originalImage=state.previewImage||makeFallback(name,'c8b8a9');state.clothes.unshift({id:`piece-${Date.now()}`,name,category,color,style:style.split(/[、,，\s]+/).filter(Boolean),season:[season],keywords:data.get('keywords').split(/[、,，\s]+/).filter(Boolean),folders:folder?[folder]:[],worn:0,image:originalImage,originalImage,cutoutImage:''});save();closeModal();renderAll();toast('已保存原图；接入云端抠图后会自动生成透明底图');setView('wardrobe');}
function adjustActiveCanvas(action){const layout=state.canvasLayout[state.activeCanvasPiece];if(!layout)return;if(action==='larger')layout.scale=Math.min(1.6,+(layout.scale+.1).toFixed(2));if(action==='smaller')layout.scale=Math.max(.35,+(layout.scale-.1).toFixed(2));if(action==='rotate')layout.rotation=(layout.rotation+15)%360;if(action==='front')layout.z=Math.max(...Object.values(state.canvasLayout).map(item=>item.z||0),0)+1;saveCanvas();renderCanvas();}
function reset(){if(!confirm('确定重置所有本地衣物和搭配数据吗？'))return;state.clothes=structuredClone(seed);state.outfits=[];state.selected=[];state.filters={category:'',color:'',style:''};state.canvasLayout={};state.folders=[];state.activeFolder='';localStorage.removeItem(STORAGE_KEY);localStorage.removeItem(OUTFIT_STORAGE_KEY);localStorage.removeItem(CANVAS_STORAGE_KEY);localStorage.removeItem(FOLDER_STORAGE_KEY);renderAll();toast('已恢复演示数据');}
document.addEventListener('click',event=>{const button=event.target.closest('button,a,[data-piece]');if(!button)return;if(button.dataset.nav){event.preventDefault();setView(button.dataset.nav);}if(button.dataset.go){event.preventDefault();setView(button.dataset.go);}if(button.dataset.openAdd!==undefined)openModal();if(button.dataset.folder){state.activeFolder=button.dataset.folder;state.filters={category:'',color:'',style:''};renderWardrobe();window.scrollTo({top:0,behavior:'smooth'});}if(button.id==='close-folder'){state.activeFolder='';state.filters={category:'',color:'',style:''};renderWardrobe();}if(button.id==='add-folder'){const name=window.prompt('输入新分类名称，例如：打底衫');if(name?.trim()){state.folders.push({id:`folder-${Date.now()}`,name:name.trim()});saveFolders();renderWardrobe();}}if(button.dataset.filter){state.filters[button.dataset.filter]=button.dataset.value;renderWardrobe();}if(button.id==='clear-filters'){state.filters={category:'',color:'',style:''};renderWardrobe();}if(button.id==='clear-selection'){state.selected=[];renderWardrobe();renderStudio();}if(button.id==='send-to-studio')setView('studio');if(button.id==='open-ootd')setView('ootd');if(button.id==='save-manual-outfit')saveManualOutfit();if(button.id==='generate-outfit')generateOutfit();if(button.id==='close-modal'||button.id==='cancel-modal')closeModal();if(button.id==='reset-data')reset();if(button.id==='mobile-add')openModal();if(button.dataset.remove)togglePiece(button.dataset.remove);if(button.dataset.canvasAdjust)adjustActiveCanvas(button.dataset.canvasAdjust);const card=button.closest('[data-piece]');if(card)togglePiece(card.dataset.piece);});
document.addEventListener('pointerdown',event=>{const piece=event.target.closest('[data-canvas-piece]');if(!piece)return;const canvas=$('#outfit-canvas'),layout=state.canvasLayout[piece.dataset.canvasPiece];if(!canvas||!layout)return;const rect=canvas.getBoundingClientRect();state.activeCanvasPiece=piece.dataset.canvasPiece;dragging={id:piece.dataset.canvasPiece,rect,offsetX:event.clientX-(rect.left+rect.width*layout.x/100),offsetY:event.clientY-(rect.top+rect.height*layout.y/100)};piece.setPointerCapture?.(event.pointerId);layout.z=Math.max(...Object.values(state.canvasLayout).map(item=>item.z||0),0)+1;renderCanvas();event.preventDefault();});
document.addEventListener('pointermove',event=>{if(!dragging)return;const{id,rect,offsetX,offsetY}=dragging,layout=state.canvasLayout[id];layout.x=Math.max(8,Math.min(92,((event.clientX-rect.left-offsetX)/rect.width)*100));layout.y=Math.max(8,Math.min(92,((event.clientY-rect.top-offsetY)/rect.height)*100));const node=$(`[data-canvas-piece="${id}"]`);if(node){node.style.setProperty('--x',`${layout.x}%`);node.style.setProperty('--y',`${layout.y}%`);}});
document.addEventListener('pointerup',()=>{if(!dragging)return;saveCanvas();dragging=null;});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!$('#add-modal').hidden)closeModal();if((event.key==='Enter'||event.key===' ')&&event.target.matches('[data-piece]')){event.preventDefault();togglePiece(event.target.dataset.piece);}});
$('#photo-input').addEventListener('change',event=>{const file=event.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{state.previewImage=reader.result;$('#upload-preview').innerHTML=`<img src="${reader.result}" alt="待上传衣物预览">`;};reader.readAsDataURL(file);});
$('#add-form').addEventListener('submit',addPiece);$('#add-modal').addEventListener('click',event=>{if(event.target===$('#add-modal'))closeModal();});window.addEventListener('hashchange',()=>setView(location.hash.slice(1)||'wardrobe'));load();renderAll();setView(location.hash.slice(1)||'wardrobe');
